<?php $m=$maintenance;$counts=$m['counts']; ?>
<section class="ops-grid">
<section class="panel" style="padding:20px"><h2>Cron & version</h2><div class="ops-list"><?php foreach ([['Cron status',$m['cron_health']],['Code version',$m['code_version']],['Installed version',$m['meta']['installed_version']??'Unknown'],['Last run',display_date($m['meta']['cron_last_completed_at']??null)],['Last cleanup',display_date($m['meta']['last_retention_cleanup_at']??null)]] as [$label,$value]): ?><div class="ops-metric"><span><?= e($label) ?></span><strong><?= e((string)$value) ?></strong></div><?php endforeach; ?></div><?php if(!$m['version_match']): ?><p class="ops-warn">Version mismatch. Verify the SQL upgrade was applied.</p><?php endif; ?></section>
<section class="panel" style="padding:20px"><h2>Storage & database</h2><p>Required tables: <?= $m['missing_tables']?'Missing: '.e(implode(', ',$m['missing_tables'])):'Available' ?></p><div class="ops-list"><?php foreach($m['storage'] as $label=>$available): ?><div class="ops-metric"><span><?= e(ucfirst($label)) ?></span><strong class="<?= $available?'ops-ok':'ops-warn' ?>"><?= $available?'Writable':'Not writable' ?></strong></div><?php endforeach; ?></div></section>
<section class="panel" style="padding:20px"><h2>Monitoring & integrity</h2><p>Counts are diagnostics only. No automatic incident repair is performed.</p><div class="ops-list"><?php foreach($counts as $label=>$value): ?><div class="ops-metric"><span><?= e($label) ?></span><strong class="<?= $value===null||($value>0 && !in_array($label,['Active Super Admins','Active Admins','Pending notifications','Failed notifications'],true))?'ops-warn':'' ?>"><?= $value===null?'Unavailable':(int)$value ?></strong></div><?php endforeach; ?></div></section>
</section>
<section class="panel" style="padding:20px;margin-top:18px"><div class="panel-header"><div><h2>Maintenance actions</h2><p>Actions are limited and logged. Confirm each operation before running it.</p></div></div><div class="ops-grid">
<?php foreach ([['cleanup','Run retention cleanup','Delete up to 1,000 old raw check rows and 1,000 eligible delivery rows.'],['aggregates','Process pending analytics','Aggregate up to 500 unprocessed scheduled checks. Existing aggregates are preserved.'],['schedules','Repair missing schedules','Schedule up to 100 active monitors whose next check is missing. No checks or incidents are invented.']] as [$action,$label,$description]): ?>
<form method="post" action="<?= e(admin_url('maintenance')) ?>" class="panel" style="padding:16px"><?= \Monitor\Core\Security::csrfField() ?><input type="hidden" name="action" value="<?= e($action) ?>"><h3><?= e($label) ?></h3><p><?= e($description) ?></p><label class="monitor-toggle"><input type="checkbox" name="confirm_action" value="yes" required><span><strong>Confirm operation</strong></span></label><div class="action-row"><button class="button secondary" type="submit">Run action</button></div></form>
<?php endforeach; ?></div></section>
<section class="panel" style="padding:20px;margin-top:18px"><div class="panel-header"><div><h2>Recent maintenance activity</h2><p>Actions are summarized without credentials or raw SQL.</p></div></div><?php if(!$maintenanceLogs): ?><p>No maintenance actions recorded.</p><?php else: ?><div class="admin-table-wrap"><table class="monitor-table"><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Summary</th></tr></thead><tbody><?php foreach($maintenanceLogs as $entry): ?><tr><td><?= e(display_date($entry['created_at'])) ?></td><td><?= e($entry['actor']??'Former administrator') ?></td><td><?= e($entry['action']) ?></td><td class="ops-log"><?= e($entry['summary']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>